from collections import deque


# 判断一个状态是否满足所有极大连通块大小均为奇数
def check(state, n, m):
    visited = [[False] * m for _ in range(n)]
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # 获取某个位置的颜色，0表示白子，1表示黑子
    def get_color(x, y):
        idx = x * m + y
        return (state >> idx) & 1

    for i in range(n):
        for j in range(m):
            if visited[i][j]:
                continue

            # 从当前点开始BFS，统计同色连通块大小
            color = get_color(i, j)
            q = deque()
            q.append((i, j))
            visited[i][j] = True
            size = 0

            while q:
                x, y = q.popleft()
                size += 1

                for dx, dy in dirs:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny]:
                        if get_color(nx, ny) == color:
                            visited[nx][ny] = True
                            q.append((nx, ny))

            # 如果某个极大连通块大小为偶数，则不合法
            if size % 2 == 0:
                return False

    return True


# 统计所有合法布局数量
def solve(n, m):
    total = n * m
    ans = 0

    # 枚举每一种黑白布局
    for state in range(1 << total):
        if check(state, n, m):
            ans += 1

    return ans


if __name__ == "__main__":
    n, m = map(int, input().split())
    print(solve(n, m))
```

